-- Uganda tax law structure (law-index.json, built by scripts/compendium-index.mjs).
-- Adds the Acts the register lacked, records chapter numbers from the 2024
-- revised edition, and one reviewable knowledge record per Act and set of
-- regulations. Only statutory structure is used: no section wording.
--
-- Source: the Arrangement of Sections in a FY 2024/25 compendium of Uganda
-- tax laws. The compiler claims copyright in the compilation (selection,
-- arrangement, tracked amendments, footnotes), so none of that is stored;
-- the compendium itself is a metadata-only record. Everything stays
-- TODO_VERIFY against the Uganda Law Reform Commission's official edition.
-- Idempotent.

SET search_path TO taxcomp;

-- The register held the Tax Appeals Tribunals Act as Cap. 345, its number in
-- the 2000 edition. The 2024 revised edition numbers it Cap. 341.
UPDATE law_statutes SET chapter = 'Cap. 341', title = 'Tax Appeals Tribunals Act',
  note = 'Cap. 341 in the Laws of Uganda, Revised Edition 2024, as printed in a FY 2024/25 compendium (the register previously showed Cap. 345, the 2000 edition number). TODO_VERIFY against the ULRC edition and the exact ULII link.'
WHERE id = 'tata' AND chapter = 'Cap. 345';

UPDATE law_statutes SET note = note || ' A FY 2024/25 compendium of the 2024 revised laws also gives ' || chapter || '.'
WHERE id IN ('ita', 'vata', 'tpca', 'eda') AND note NOT LIKE '%FY 2024/25 compendium%';

